import React from "react";
import apiKeys from "./apiKeys";
import Clock from "react-live-clock";
import Forcast from "./forcast";
import loader from "./images/WeatherIcons.gif";
import ReactAnimatedWeather from "react-animated-weather";

const dateBuilder = (d) => {
  let months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];

  let days = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
  ];

  let day = days[d.getDay()];
  let date = d.getDate();
  let month = months[d.getMonth()];
  let year = d.getFullYear();

  return `${day}, ${date} ${month} ${year}`;
};

const defaults = {
  color: "white",
  size: 112,
  animate: true,
};

class Weather extends React.Component {

  state = {
    lat: undefined,
    lon: undefined,
    errorMessage: undefined,
    temperatureC: undefined,
    temperatureF: undefined,
    city: undefined,
    country: undefined,
    humidity: undefined,
    description: undefined,
    icon: "CLEAR_DAY",
    sunrise: undefined,
    sunset: undefined,
    main: undefined,
  };

  componentDidMount() {

    if (navigator.geolocation) {

      this.getPosition()
        .then((position) => {

          this.getWeather(
            position.coords.latitude,
            position.coords.longitude
          );

        })
        .catch(() => {

          this.getWeather(28.67, 77.22);

          alert(
            "Location permission denied. Default weather will be shown."
          );

        });

    } else {

      alert("Geolocation not available");

    }

    this.timerID = setInterval(() => {

      this.getWeather(this.state.lat, this.state.lon);

    }, 600000);

  }

  componentWillUnmount() {
    clearInterval(this.timerID);
  }

  getPosition = (options) => {

    return new Promise(function (resolve, reject) {

      navigator.geolocation.getCurrentPosition(
        resolve,
        reject,
        options
      );

    });

  };

  getTimeFromUnixTimeStamp = (unixTimestamp) => {

    let date = new Date(unixTimestamp * 1000);

    let hours = date.getHours();
    let minutes = date.getMinutes();

    return `${hours}:${minutes}`;

  };

  getWeather = async (lat, lon) => {

    try {

      const api_call = await fetch(
        `${apiKeys.base}weather?lat=${lat}&lon=${lon}&units=metric&appid=${apiKeys.key}`
      );

      const data = await api_call.json();

      console.log(data);

      this.setState({

        lat: lat,
        lon: lon,

        city: data.name || "Kolkata",

        temperatureC: data.main?.temp
          ? Math.round(data.main.temp)
          : 25,

        temperatureF: data.main?.temp
          ? Math.round(data.main.temp * 1.8 + 32)
          : 77,

        humidity: data.main?.humidity || 50,

        main: data.weather?.[0]?.main || "Clear",

        country: data.sys?.country || "IN",

        sunrise: data.sys
          ? this.getTimeFromUnixTimeStamp(data.sys.sunrise)
          : "",

        sunset: data.sys
          ? this.getTimeFromUnixTimeStamp(data.sys.sunset)
          : "",

      });

      switch (data.weather?.[0]?.main) {

        case "Haze":
          this.setState({ icon: "CLEAR_DAY" });
          break;

        case "Clouds":
          this.setState({ icon: "CLOUDY" });
          break;

        case "Rain":
          this.setState({ icon: "RAIN" });
          break;

        case "Snow":
          this.setState({ icon: "SNOW" });
          break;

        case "Dust":
          this.setState({ icon: "WIND" });
          break;

        case "Drizzle":
          this.setState({ icon: "SLEET" });
          break;

        case "Fog":
          this.setState({ icon: "FOG" });
          break;

        case "Smoke":
          this.setState({ icon: "FOG" });
          break;

        case "Tornado":
          this.setState({ icon: "WIND" });
          break;

        default:
          this.setState({ icon: "CLEAR_DAY" });

      }

    } catch (error) {

      console.log(error);

      this.setState({

        city: "Kolkata",
        country: "IN",
        temperatureC: 25,
        temperatureF: 77,
        humidity: 50,
        main: "Clear",

      });

    }

  };

  render() {

    if (this.state.city) {

      return (

        <React.Fragment>

          <div className="city">

            <div className="title">

              <h2>{this.state.city}</h2>
              <h3>{this.state.country}</h3>

            </div>

            <div className="mb-icon">

              <ReactAnimatedWeather
                icon={this.state.icon}
                color={defaults.color}
                size={defaults.size}
                animate={defaults.animate}
              />

              <p>{this.state.main}</p>

            </div>

            <div className="date-time">

              <div className="dmy">

                <div className="current-time">

                  <Clock
                    format="HH:mm:ss"
                    interval={1000}
                    ticking={true}
                  />

                </div>

                <div className="current-date">
                  {dateBuilder(new Date())}
                </div>

              </div>

              <div className="temperature">

                <p>
                  {this.state.temperatureC}°
                  <span>C</span>
                </p>

              </div>

            </div>

          </div>

          <Forcast
            icon={this.state.icon}
            weather={this.state.main}
          />

        </React.Fragment>

      );

    } else {

      return (

        <React.Fragment>

          <img
            src={loader}
            alt="loading"
            style={{
              width: "50%",
              WebkitUserDrag: "none"
            }}
          />

          <h3
            style={{
              color: "white",
              fontSize: "22px",
              fontWeight: "600"
            }}
          >
            Detecting your location
          </h3>

          <h3
            style={{
              color: "white",
              marginTop: "10px"
            }}
          >
            Your current location will be displayed on the App
            <br />
            & used for calculating Real time weather.
          </h3>

        </React.Fragment>

      );

    }

  }

}

export default Weather;
